import { IHotel } from '@hotel-booking-platform/shared-types/src/domain/hotel';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import React, { useEffect, useState } from 'react';
import {
    ActivityIndicator,
    FlatList,
    Image,
    SafeAreaView,
    StatusBar,
    Text,
    TextInput,
    TouchableOpacity,
    TouchableWithoutFeedback,
    View
} from 'react-native';
// 关键：使用 Expo 内置图标
import { MaterialIcons } from '@expo/vector-icons';
import { RootStackParamList } from '../../navigation/types';
import { styles } from './index.styles';

type Props = NativeStackScreenProps<RootStackParamList, 'HotelList'>;

// 静态筛选配置
const SORT_OPTIONS = [
    { label: '欢迎度排序', value: 'popular' },
    { label: '好评优先', value: 'score_desc' },
    { label: '低价优先', value: 'price_asc' },
    { label: '高价优先', value: 'price_desc' },
];

const HotelListScreen = ({ route, navigation }: Props) => {
    const { city = '', startDate = '', endDate = '', name = '', brand = '' } = route.params || {};

    const handleDateChange = (dateStr: string) => {
        if (!dateStr) return '';
        return dateStr.split('-').slice(1).join('-');
    }
    const newStartDate = handleDateChange(startDate);
    const newEndDate = handleDateChange(endDate);

    const [hotels, setHotels] = useState<IHotel[]>([]);
    const [loading, setLoading] = useState(false);
    const [activeTab, setActiveTab] = useState<number | null>(null);
    const [selectedSort, setSelectedSort] = useState('popular');

    const loadData = (isRefresh = false) => {
        if (loading) return;
        setLoading(true);
        setTimeout(() => {
            const mockData: IHotel[] = Array.from({ length: 5 }).map((_, i) => ({
                id: Math.random().toString(),
                name: `嘉豪精品酒店 ${hotels.length + i + 1}号店`,
                image: 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=400&q=80',
                score: 4.8,
                starRating: 4, // 假设数据中有这个字段
                comments: 1258,
                address: '朝阳区三里屯路 | 距您直线2.3km',
                tags: ['免费取消', '含早餐', '近地铁'],
                price: 588 + i * 20,
            }));
            setHotels(prev => isRefresh ? mockData : [...prev, ...mockData]);
            setLoading(false);
        }, 600);
    };

    useEffect(() => { loadData(true); }, []);

    // 渲染酒店卡片
    const renderHotelItem = ({ item }: { item: IHotel }) => (
        <TouchableOpacity
            activeOpacity={0.9}
            style={styles.hotelItem}
            onPress={() => navigation.navigate('HotelDetail', { hotelId: item.id, hotelName: item.name })}
        >
            <Image source={{ uri: item.image }} style={styles.hotelImage} />
            <View style={styles.infoArea}>
                <View>
                    <Text style={styles.hotelName} numberOfLines={1}>{item.name}</Text>

                    {/* 优化的星级渲染 */}
                    <View style={styles.starScoreRow}>
                        <View style={styles.starContainer}>
                            {[1, 2, 3, 4, 5].map((s) => (
                                <MaterialIcons
                                    key={s}
                                    name="star"
                                    size={14}
                                    color={s <= (item.starRating || 4) ? "#FFB400" : "#E0E0E0"}
                                />
                            ))}
                        </View>
                        <Text style={styles.scoreText}>{item.score}分</Text>
                        <Text style={styles.commentText}>{item.comments}评价</Text>
                    </View>

                    <Text style={styles.addressText} numberOfLines={1}>{item.address}</Text>

                    <View style={styles.tagRow}>
                        {item.tags.map((tag, idx) => (
                            <View key={idx} style={styles.hotelTag}>
                                <Text style={styles.hotelTagText}>{tag}</Text>
                            </View>
                        ))}
                    </View>
                </View>
                <View style={styles.priceContainer}>
                    <Text style={styles.priceSymbol}>¥</Text>
                    <Text style={styles.priceText}>{item.price}</Text>
                    <Text style={styles.priceUnit}>起</Text>
                </View>
            </View>
        </TouchableOpacity>
    );

    const renderDropdown = () => {
        if (activeTab === null) return null;
        return (
            <View style={styles.dropdownContainer}>
                <TouchableWithoutFeedback onPress={() => setActiveTab(null)}><View style={styles.mask} /></TouchableWithoutFeedback>
                <View style={styles.dropdownContent}>
                    {activeTab === 0 && (
                        <View style={styles.dropdownList}>
                            {SORT_OPTIONS.map((opt) => (
                                <TouchableOpacity key={opt.value} style={styles.dropdownItem} onPress={() => { setSelectedSort(opt.value); setActiveTab(null); }}>
                                    <Text style={[styles.dropdownItemText, selectedSort === opt.value && styles.activeDropdownItemText]}>{opt.label}</Text>
                                    {selectedSort === opt.value && <MaterialIcons name="check" size={20} color="#0086F6" />}
                                </TouchableOpacity>
                            ))}
                        </View>
                    )}
                    {activeTab !== 0 && <View style={{ padding: 30, alignItems: 'center' }}><Text style={{ color: '#999' }}>更多筛选条件...</Text></View>}
                </View>
            </View>
        );
    };

    return (
        <SafeAreaView style={styles.container}>
            <StatusBar barStyle="dark-content" />
            <View style={[styles.headerContainer, { zIndex: 10 }]}>
                {/* 搜索框 */}
                <View style={styles.searchBarContainer}>
                    <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
                        <MaterialIcons name="chevron-left" size={30} color="#333" />
                    </TouchableOpacity>
                    <View style={styles.searchMainContent}>
                        <Text style={styles.cityText}>{city || '上海'}</Text>
                        <View style={styles.dateVerticalContainer}>
                            <View style={styles.dateRow}><Text style={styles.dateLabel}>住</Text><Text style={styles.dateValue}>{newStartDate || '02-04'}</Text></View>
                            <View style={styles.dateRow}><Text style={styles.dateLabel}>离</Text><Text style={styles.dateValue}>{newEndDate || '02-05'}</Text></View>
                        </View>
                        <Text style={styles.nightCountText}>1晚</Text>
                        <View style={styles.verticalDivider} />
                        <View style={styles.keywordContainer}>
                            <MaterialIcons name="search" size={18} color="#999" style={{ marginRight: 4 }} />
                            <TextInput style={styles.keywordPlaceholder} placeholder="位置/品牌/酒店" placeholderTextColor="#ccc" />
                        </View>
                    </View>
                </View>

                {/* 筛选 Tab */}
                <View style={styles.filterRow}>
                    {['排序', '位置', '价格/星级', '筛选'].map((label, i) => (
                        <TouchableOpacity key={i} style={styles.filterItem} onPress={() => setActiveTab(activeTab === i ? null : i)}>
                            <Text style={[styles.filterText, activeTab === i && styles.activeFilterText]}>
                                {i === 0 ? SORT_OPTIONS.find(o => o.value === selectedSort)?.label : label}
                            </Text>
                            <MaterialIcons name={activeTab === i ? "arrow-drop-up" : "arrow-drop-down"} size={18} color={activeTab === i ? "#0086F6" : "#999"} />
                        </TouchableOpacity>
                    ))}
                </View>
                {renderDropdown()}
            </View>

            <FlatList
                data={hotels}
                renderItem={renderHotelItem}
                keyExtractor={item => item.id}
                onEndReached={() => loadData()}
                ListFooterComponent={loading ? <ActivityIndicator style={{ margin: 20 }} color="#0086F6" /> : null}
            />
        </SafeAreaView>
    );
};

export default HotelListScreen;
